// --- Begin migration_enterprise.php ---

require_once __DIR__ . '/../includes/database.php';

try {
    $db = db();
    
    // 1. Saved Properties
    $db->exec("CREATE TABLE IF NOT EXISTS `saved_properties` (
        `id` INT AUTO_INCREMENT PRIMARY KEY,
        `user_id` INT NOT NULL,
        `property_id` INT NOT NULL,
        `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
        UNIQUE KEY `unique_save` (`user_id`, `property_id`),
        FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON DELETE CASCADE,
        FOREIGN KEY (`property_id`) REFERENCES `properties`(`id`) ON DELETE CASCADE
    ) ENGINE=InnoDB;");
    echo "Table 'saved_properties' created/verified.<br>\n";

    // 2. Saved Searches
    $db->exec("CREATE TABLE IF NOT EXISTS `saved_searches` (
        `id` INT AUTO_INCREMENT PRIMARY KEY,
        `user_id` INT NOT NULL,
        `search_name` VARCHAR(100),
        `criteria` JSON NOT NULL,
        `receive_alerts` TINYINT(1) DEFAULT 1,
        `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
        FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON DELETE CASCADE
    ) ENGINE=InnoDB;");
    echo "Table 'saved_searches' created/verified.<br>\n";

    // 3. Tour Schedules
    $db->exec("CREATE TABLE IF NOT EXISTS `tour_schedules` (
        `id` INT AUTO_INCREMENT PRIMARY KEY,
        `user_id` INT NOT NULL,
        `property_id` INT NOT NULL,
        `tour_date` DATE NOT NULL,
        `tour_time` TIME NOT NULL,
        `tour_type` ENUM('in-person', 'video') DEFAULT 'in-person',
        `status` ENUM('pending', 'approved', 'rejected') DEFAULT 'pending',
        `message` TEXT,
        `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
        FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON DELETE CASCADE,
        FOREIGN KEY (`property_id`) REFERENCES `properties`(`id`) ON DELETE CASCADE
    ) ENGINE=InnoDB;");
    echo "Table 'tour_schedules' created/verified.<br>\n";

    // 4. Update 'users' table role ENUM to include 'agent'
    // MySQL ALTER TABLE ENUM requires redefining the ENUM
    $db->exec("ALTER TABLE `users` MODIFY COLUMN `role` ENUM('user', 'admin', 'agent') DEFAULT 'user';");
    echo "Table 'users' altered to include 'agent' role.<br>\n";

    echo "<h3>Migration completed successfully!</h3>";

} catch (PDOException $e) {
    echo "Error: " . $e->getMessage() . "<br>\n";
}

// --- End migration_enterprise.php ---


