// --- Begin migration_rich_media.php ---

require_once __DIR__ . '/../includes/database.php';

try {
    $db = db();
    
    // Add columns to properties table
    $columns_to_add = [
        'virtual_tour_url' => "VARCHAR(255) DEFAULT NULL",
        'video_url' => "VARCHAR(255) DEFAULT NULL",
        'floor_plan_image' => "VARCHAR(255) DEFAULT NULL"
    ];

    foreach ($columns_to_add as $col_name => $col_def) {
        try {
            $db->exec("ALTER TABLE `properties` ADD COLUMN `$col_name` $col_def;");
            echo "Column '$col_name' added successfully.<br>\n";
        } catch (PDOException $e) {
            // Error 1060 is "Duplicate column name", which means it already exists. We can ignore it safely.
            if ($e->getCode() == '42S21') { 
                echo "Column '$col_name' already exists.<br>\n";
            } else {
                echo "Error adding '$col_name': " . $e->getMessage() . "<br>\n";
            }
        }
    }

    echo "<h3>Migration completed successfully!</h3>";

} catch (PDOException $e) {
    echo "Error: " . $e->getMessage() . "<br>\n";
}

// --- End migration_rich_media.php ---
